corrected_code:
const passport = require('passport');
const CustomStrategy = require('passport-custom').Strategy;
const { BadgeReader, AccessLog } = require('../models/iot');

passport.use('rfid-badge', new CustomStrategy(async (req, done) => {
  const { badgeRfid, doorZoneId } = req.body;

  const badge = await BadgeReader.findOne({ rfid: badgeRfid, active: true });
  if (!badge) {
    return done(null, false, { message: 'Invalid RFID badge' });
  }

  if (!badge.authorizedZones.includes(doorZoneId)) {
    return done(null, false, { message: 'Forbidden: badge lacks clearance for requested zone' });
  }

  req.accessZone = doorZoneId;
  return done(null, { badgeId: badge.id, holderName: badge.holderName });
}));
